// Tiny in-memory store so the Server Action and the Server Component share
// state. In a real app this would be a database call. Module-level state is
// preserved across requests on a single server instance.
type Preferences = {
  notificationsEnabled: boolean;
};

const preferencesByUser = new Map<string, Preferences>();

const DEFAULT_USER = "me";

export function getPreferences(userId: string = DEFAULT_USER): Preferences {
  return (
    preferencesByUser.get(userId) ?? {
      notificationsEnabled: false,
    }
  );
}

export function toggleNotifications(userId: string = DEFAULT_USER): boolean {
  const current = getPreferences(userId);
  const next = !current.notificationsEnabled;
  preferencesByUser.set(userId, { notificationsEnabled: next });
  return next;
}

