import { revalidatePath } from "next/cache";
import { toggleNotifications } from "./notifications-store";

/**
 * Toggles the user's notification preference on/off.
 *
 * After mutating the data, we call `revalidatePath` with the current route.
 * This is Next.js's recommended way to refresh the *current* page's data from
 * within a Server Action: it purges the cached Server Component data for the
 * path and re-renders it in place, without navigating/redirecting to another
 * page. The client stays on the same URL and sees the updated preference.
 */
export async function toggleNotificationPreference(): Promise<void> {
  toggleNotifications();
  revalidatePath("/");
}

