import { toggleNotificationPreference } from "./actions";
import { getPreferences } from "./notifications-store";

export default function Home() {
  const { notificationsEnabled } = getPreferences();

  return (
    <main>
      <h1>Settings</h1>
      <p>
        Notifications are currently <strong>{notificationsEnabled ? "ON" : "OFF"}</strong>.
      </p>

      <form action={toggleNotificationPreference}>
        <button type="submit">
          {notificationsEnabled ? "Disable notifications" : "Enable notifications"}
        </button>
      </form>
    </main>
  );
}

