import { spawn } from "node:child_process";

const server = spawn("npx", ["next", "start", "-p", "3138"], {
  cwd: "/workspace",
  stdio: "ignore",
  detached: false,
});

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
await sleep(5000);

const base = "http://localhost:3138";

function extractState(html) {
  const m = html.match(/Notifications are currently <strong>([A-Z]+)<\/strong>/);
  return m ? m[1] : null;
}

// 1. Initial render
const first = await fetch(base + "/");
const firstHtml = await first.text();
console.log("initial:", extractState(firstHtml));

// 2. Find the server action id from the form
const actionIdMatch = firstHtml.match(/\$ACTION_ID_([0-9a-f]+)/);
if (!actionIdMatch) {
  console.log("no action id found");
  server.kill("SIGTERM");
  process.exit(1);
}
const actionId = actionIdMatch[1];
console.log("action id:", actionId);

// 3. POST to the action (server action endpoint is the same path)
const formData = new FormData();
formData.append("0", ""); // $ACTION_ID_... is encoded; Next expects $ACTION_ID_1 field
const post = await fetch(base + "/", {
  method: "POST",
  headers: {
    "Content-Type": "application/x-www-form-urlencoded",
    Accept: "text/x-component",
    "Next-Action": actionId,
  },
  body: "",
});
console.log("post status:", post.status, "redirected:", post.redirected, "url:", post.url);
const postBody = await post.text();
console.log("post body (first 200):", postBody.slice(0, 200));

// 4. Re-fetch the page to confirm updated preference (no redirect happened)
const second = await fetch(base + "/", { headers: { "Cache-Control": "no-cache" } });
const secondHtml = await second.text();
console.log("after toggle:", extractState(secondHtml));

server.kill("SIGTERM");
process.exit(0);

