import { spawn } from "node:child_process";

const server = spawn("npx", ["next", "start", "-p", "3141"], {
  cwd: "/workspace",
  stdio: "ignore",
});
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
await sleep(5000);

const base = "http://localhost:3141";
const stateRe = /Notifications are currently <strong>([A-Z]+)<\/strong>/;
const extract = (html) => (html.match(stateRe) || [])[1] || null;

const first = await fetch(base + "/");
const firstHtml = await first.text();
console.log("initial state:", extract(firstHtml));

const idMatch = firstHtml.match(/\$ACTION_ID_([0-9a-f]+)/);
if (!idMatch) throw new Error("no action id");
const actionId = idMatch[1];
console.log("action id:", actionId);

// Invoke the server action: POST to the same path with the $ACTION_ID field
// and the Next-Action header set to the action id.
const form = new FormData();
form.append("$ACTION_ID_" + actionId, "");
const post = await fetch(base + "/", {
  method: "POST",
  headers: { "Next-Action": actionId },
  body: form,
});
console.log("post status:", post.status, "redirected:", post.redirected, "final url:", post.url);

// Re-fetch the page to confirm the preference was toggled in place (no redirect).
const second = await fetch(base + "/", { headers: { "Cache-Control": "no-cache" } });
const secondHtml = await second.text();
console.log("state after toggle:", extract(secondHtml));

server.kill("SIGTERM");
const ok = extract(firstHtml) === "OFF" && extract(secondHtml) === "ON" && !post.redirected;
console.log("RESULT:", ok ? "PASS" : "FAIL");
process.exit(ok ? 0 : 1);

