import { spawn } from "node:child_process";

const server = spawn("npx", ["next", "start", "-p", "3146"], {
  cwd: "/workspace",
  stdio: "ignore",
});
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
await sleep(5000);

const base = "http://localhost:3146";
const stateRe = /Notifications are currently <strong>([A-Z]+)<\/strong>/;
const btnRe = /<button type="submit">([^<]+)<\/button>/;
const extract = (html, re) => (html.match(re) || [])[1] || null;

// 1. Initial render
const first = await fetch(base + "/");
const firstHtml = await first.text();
console.log("initial state:", extract(firstHtml, stateRe), "| button:", extract(firstHtml, btnRe));

const idMatch = firstHtml.match(/\$ACTION_ID_([0-9a-f]+)/);
const actionId = idMatch[1];

// 2. Submit the form the way a browser does without JS (progressive enhancement):
//    multipart/form-data POST to the same URL with the $ACTION_ID field.
//    Next runs the server action, calls revalidatePath, and returns the
//    re-rendered page at the SAME url (no redirect).
const form = new FormData();
form.append("$ACTION_ID_" + actionId, "");
const post = await fetch(base + "/", { method: "POST", body: form, redirect: "manual" });
console.log("post status:", post.status, "| redirected:", post.redirected, "| location:", post.headers.get("location"), "| final url:", post.url);
const postHtml = await post.text();
console.log("post response state:", extract(postHtml, stateRe), "| button:", extract(postHtml, btnRe));

// 3. A fresh GET also reflects the toggled state (cache revalidated).
const second = await fetch(base + "/", { headers: { "Cache-Control": "no-cache" } });
const secondHtml = await second.text();
console.log("fresh GET state:", extract(secondHtml, stateRe));

// 4. Toggle back to OFF to prove idempotent toggling.
const form2 = new FormData();
form2.append("$ACTION_ID_" + actionId, "");
const post2 = await fetch(base + "/", { method: "POST", body: form2, redirect: "manual" });
const post2Html = await post2.text();
console.log("second toggle state:", extract(post2Html, stateRe));

server.kill("SIGTERM");

const ok =
  extract(firstHtml, stateRe) === "OFF" &&
  !post.redirected &&
  post.headers.get("location") === null &&
  extract(postHtml, stateRe) === "ON" &&
  extract(secondHtml, stateRe) === "ON" &&
  extract(post2Html, stateRe) === "OFF";
console.log("RESULT:", ok ? "PASS" : "FAIL");
process.exit(ok ? 0 : 1);

